import os
import subprocess

def git_clone(repo_url):
    try:
        subprocess.run(['git', 'clone', repo_url], check=True, capture_output=True)
        print(f"Repository cloned successfully from {repo_url}")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error cloning repository: {e.stderr.decode()}")
        return False

def git_create_branch(branch_name, start_point="main", checkout=True):
    try:
        subprocess.run(['git', 'checkout', start_point], check=True, capture_output=True)
        subprocess.run(['git', 'branch', branch_name], check=True, capture_output=True)
        if checkout:
            subprocess.run(['git', 'checkout', branch_name], check=True, capture_output=True)
        print(f"Branch '{branch_name}' created and (optionally) checked out.")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error creating/checking out branch: {e.stderr.decode()}")
        return False

def fetch_issue(owner, repo, issue_number):
    try:
        import requests
        url = f"https://api.github.com/repos/{owner}/{repo}/issues/{issue_number}"
        response = requests.get(url)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        issue_data = response.json()
        return issue_data['body']
    except requests.exceptions.RequestException as e:
        print(f"Error fetching issue: {e}")
        return None

def read_file(path):
    try:
        with open(path, 'r') as f:
            return f.read()
    except FileNotFoundError:
        print(f"File not found: {path}")
        return None
    except Exception as e:
        print(f"Error reading file: {e}")
        return None

def edit_file(path, old_content, new_content):
    try:
        file_content = read_file(path)
        if file_content is None:
            return False

        new_file_content = file_content.replace(old_content, new_content)

        with open(path, 'w') as f:
            f.write(new_file_content)
        return True
    except Exception as e:
        print(f"Error editing file: {e}")
        return False

def git_commit(message):
    try:
        subprocess.run(['git', 'add', '.'], check=True, capture_output=True)
        subprocess.run(['git', 'commit', '-m', message], check=True, capture_output=True)
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error committing changes: {e.stderr.decode()}")
        return False

def git_push(force=False):
    try:
        command = ['git', 'push', 'origin', 'HEAD']
        if force:
            command.append('--force')
        subprocess.run(command, check=True, capture_output=True)
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error pushing changes: {e.stderr.decode()}")
        return False

def create_pr(owner, repo, head_branch, base_branch, title, body):
    try:
        import requests
        url = "https://api.github.com/repos/{owner}/{repo}/pulls".format(
            owner=owner, repo=repo
        )
        headers = {
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
        }
        data = {
            "title": title,
            "body": body,
            "head": head_branch,
            "base": base_branch,
        }
        response = requests.post(url, headers=headers, json=data)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error creating PR: {e}")
        return None
